    bne     @place                  ; $9A7C  not placed: a spot
; (code below not executed in the test movies)
    lda     #$15                    ; $9A7E  placed: the crystal
    sta     enemyType,x             ; $9A80
; (end of code not executed in the test movies)

@place:
    lda     #$62                    ; $9A82  at (X $7C, Y $62)
    sta     objY+1,x                ; $9A84
    lda     #$7C                    ; $9A86
    sta     objX+1,x                ; $9A88
    rts                             ; $9A8A

; ---------------------------------------------------------------------------
; Crystal_Ai
;
; The crystal in its statue ($15; also drawn by the spot while it rises):
; one sprite, tile $3D, its palette cycling every frame.  Not drawn when
; its column is off screen.
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
Crystal_Ai:
    lda     drawOffscreen+1         ; $9A8B  off screen: not drawn
    and     #$08                    ; $9A8D
    bne     @done                   ; $9A8F
    ldy     objOamOffset+1,x        ; $9A91
    lda     objY+1,x                ; $9A93
    sta     oamBuffer,y             ; $9A95
    lda     #$3D                    ; $9A98  the crystal
    sta     oamBuffer+1,y           ; $9A9A
    lda     frameCounter            ; $9A9D  palette 0-3 by the frame
    and     #$03                    ; $9A9F
    sta     oamBuffer+2,y           ; $9AA1
    lda     drawScreenX+1           ; $9AA4
    sta     oamBuffer+3,y           ; $9AA6

@done:
    rts                             ; $9AA9
; (unreferenced: $9AAA-$9AD3, 42 bytes)
    .byte   $00, $00, $00, $01, $01, $01, $02, $02, $02, $03, $03, $03, $05, $05, $05, $09; $9AAA
    .byte   $09, $09, $0F, $0F, $0F, $32, $64, $64, $2C, $2C, $2C, $BC, $BC, $BC, $E8, $E8; $9ABA
    .byte   $E8, $DC, $DC, $DC, $C4, $C4, $C4, $A0, $A0, $A0                ; $9ACA

; ---------------------------------------------------------------------------
; CrystalSpot_Ai
;
; The statue where the palace's crystal goes ($14).  It keeps the palette
; flash going (CrystalSpot_FlashPalette), draws the crystal once it is
; there (objState+1 nonzero: its Y), and runs its step by enemyAiState:
; CrystalSpot_Wait, CrystalSpot_Rise, CrystalSpot_WaitMusic,
; CrystalSpot_Finish.
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
CrystalSpot_Ai:
    jsr     CrystalSpot_FlashPalette ; $9AD4
    lda     objState+1,x            ; $9AD7  crystal there?
    beq     @step                   ; $9AD9
    jsr     Crystal_Ai              ; $9ADB  draw it

@step:
    lda     enemyAiState,x          ; $9ADE
    jsr     JumpTable               ; $9AE0
; (inline jump table)
    .word   CrystalSpot_Wait        ; $9AE3
    .word   CrystalSpot_Rise        ; $9AE5
    .word   CrystalSpot_WaitMusic   ; $9AE7
    .word   CrystalSpot_Finish      ; $9AE9

; ---------------------------------------------------------------------------
; CrystalSpot_Wait
;
; While it is on screen and Link has a crystal (crystalsRemaining), wait
; for him to stand on it (touching it, his objCollision bit 2).  Then:
; freeze the game, Link in his holding-up pose (objState 3), the crystal
; at Y $A0, one crystal fewer, a sound and the fanfare, and the palace
; marked done (crystalPlaced, by palaceCode, + 2 for the regions past
; West Hyrule).
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
CrystalSpot_Wait:
    lda     drawOffscreen+1         ; $9AEB  on screen,
    bne     @done                   ; $9AED
    lda     crystalsRemaining       ; $9AEF  a crystal to place,
    beq     @done                   ; $9AF2
    jsr     Enemy_CheckLinkContact  ; $9AF4
    lda     objCollision+1,x        ; $9AF7  Link touching it,
    and     #$10                    ; $9AF9
    beq     @done                   ; $9AFB
    lda     objCollision            ; $9AFD  and standing?
    and     #$04                    ; $9AFF
    beq     @done                   ; $9B01
    inc     enemyAiState,x          ; $9B03  rise
    inc     gameFrozen              ; $9B05  freeze the game
    lda     #$03                    ; $9B07  Link holds it up
    sta     objState                ; $9B09
    lda     #$A0                    ; $9B0B  the crystal at Y $A0
    sta     objY+1,x                ; $9B0D
    dec     crystalsRemaining       ; $9B0F
    lda     #$08                    ; $9B12  a sound,
    sta     sfxRequest+3            ; $9B14
    lda     #$80                    ; $9B16  the fanfare
    sta     musicRequest            ; $9B18
    lda     currentRegion           ; $9B1A  crystalPlaced entry:
    beq     @mark                   ; $9B1D  palaceCode (+ 2 past the
    clc                             ; $9B1F  west)
    adc     #$02                    ; $9B20

@mark:
    sec                             ; $9B22  (itemOwned+7 + 1 + y =
    adc     palaceCode              ; $9B23  crystalPlaced + y)
    tay                             ; $9B26
    sta     itemOwned+7,y           ; $9B27

@done:
    rts                             ; $9B2A

; ---------------------------------------------------------------------------
; CrystalSpot_Rise
;
; Raise the crystal a pixel per frame (its Y also in objState+1, so that it
; is drawn) to Y $62, 62 frames; then start the palette flash for 98
; frames (crystalFlashTimer), the next music and a sound, and stop Link.
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
CrystalSpot_Rise:
    dec     objY+1,x                ; $9B2B  a pixel up
    lda     objY+1,x                ; $9B2D
    sta     objState+1,x            ; $9B2F  (drawn there)
    cmp     #$62                    ; $9B31  at Y $62?
    bne     @done                   ; $9B33
    sta     crystalFlashTimer       ; $9B35  flash for $62 frames
    inc     enemyAiState,x          ; $9B38
    lda     #$40                    ; $9B3A
    sta     musicRequest            ; $9B3C
    lda     #$02                    ; $9B3E
    sta     sfxRequest              ; $9B40
    lda     #$00                    ; $9B42
    sta     objXVelocity            ; $9B44

@done:
    rts                             ; $9B46

; ---------------------------------------------------------------------------
; CrystalSpot_WaitMusic
;
; When the music has ended, fill both of Link's meters
; (statMeterPending $FF, $FF).
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
CrystalSpot_WaitMusic:
    ldy     musicPlaying            ; $9B47  music over?
    bne     @done                   ; $9B4A
    dey                             ; $9B4C  y = $FF:
    sty     statMeterPending        ; $9B4D  fill magic
    sty     statMeterPending+1      ; $9B50  and life
    inc     enemyAiState,x          ; $9B53

@done:
    rts                             ; $9B55

; ---------------------------------------------------------------------------
; CrystalSpot_Finish
;
; When the meters are full: unfreeze the game; give Link exactly the
; experience he lacks for his next level (experiencePending =
; experienceNext - experience); make the spot the crystal (type $15),
; also in the area's enemy list (type byte $D5: page 3, type $15), so
; that it is the crystal from now on; clear area flag 3; and restart the
; area's music.
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
CrystalSpot_Finish:
    lda     statMeterPending        ; $9B56  meters full?
    ora     statMeterPending+1      ; $9B59
    bne     @done                   ; $9B5C
    sta     gameFrozen              ; $9B5E  unfreeze
    lda     experienceNext+1        ; $9B60  experience to the next level
    sec                             ; $9B63
    sbc     experience+1            ; $9B64
    sta     experiencePending+1     ; $9B67
    lda     experienceNext          ; $9B6A
    sbc     experience              ; $9B6D
    sta     experiencePending       ; $9B70
    ldy     enemySramIndex,x        ; $9B73  its list entry's type byte:
    iny                             ; $9B75
    lda     #$D5                    ; $9B76  page 3, the crystal
    sta     (enemyListPtr),y        ; $9B78
    lda     #$15                    ; $9B7A  the crystal now
    sta     enemyType,x             ; $9B7C
    ldx     #$02                    ; $9B7E  the area's music
    stx     musicRequest            ; $9B80
    inx                             ; $9B82  area flag 3: placed
    jsr     Area_ClearFlag          ; $9B83
    ldx     currentObject           ; $9B86

@done:
    rts                             ; $9B88

; CrystalSpot_FlashPalette: the flashing color, by the timer's bits 1-0.
CrystalSpotFlashColors:
    .byte   $12, $30, $2A, $16                                              ; $9B89

; CrystalSpot_FlashPalette: PPU string for background palette 3 ($3F0C).
CrystalSpotPaletteString:
    .byte   $3F, $0C, $04, $0F, $3C, $1C, $0C, $FF                          ; $9B8D

; ---------------------------------------------------------------------------
; CrystalSpot_FlashPalette
;
; While crystalFlashTimer counts down, queue background palette 3
; ($3F0C-$3F0F) every frame as $0F, $3C, $1C, $0C with its second color
; cycling through CrystalSpotFlashColors (by the timer's bits 1-0); on
; the last frame, the area's own colors (sramAreaPalettes+29-31) instead.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
CrystalSpot_FlashPalette:
    lda     crystalFlashTimer       ; $9B95  flashing?
    beq     @done                   ; $9B98
    dec     crystalFlashTimer       ; $9B9A
    ldy     #$07                    ; $9B9D  copy the palette string

@loop:
    lda     CrystalSpotPaletteString,y ; $9B9F
    sta     ppuBuffer0,y            ; $9BA2
    dey                             ; $9BA5
    bpl     @loop                   ; $9BA6
    lda     crystalFlashTimer       ; $9BA8  last frame?
    bne     @flash                  ; $9BAB
    lda     sramAreaPalettes+29     ; $9BAD  yes: the area's colors
    sta     ppuBuffer0+4            ; $9BB0
    lda     sramAreaPalettes+31     ; $9BB3
    sta     ppuBuffer0+6            ; $9BB6
    lda     sramAreaPalettes+30     ; $9BB9
    bne     @setColor               ; $9BBC  (always)

@flash:
    and     #$03                    ; $9BBE  no: a flash color by the timer
    tay                             ; $9BC0
    lda     CrystalSpotFlashColors,y ; $9BC1

@setColor:
    sta     ppuBuffer0+5            ; $9BC4
    lda     #$07                    ; $9BC7
    sta     ppuBuffer0Len           ; $9BC9

@done:
    rts                             ; $9BCC

; Enemy_FireAimedBall: X speed of the ball by Link's distance step d.
AimedBallXSpeeds:
    .byte   $06, $0A, $0D, $0F, $11, $12                                    ; $9BCD
; (unreferenced: $9BD3-$9BD4, 2 bytes)
    .byte   $13, $13                                                        ; $9BD3

; Enemy_FireAimedBall: Y speed (down) of the ball by d.
AimedBallYSpeeds:
    .byte   $16, $14, $13, $11, $0F, $0E                                    ; $9BD5
; (unreferenced: $9BDB-$9BDC, 2 bytes)
    .byte   $0D, $0B                                                        ; $9BDB

; ---------------------------------------------------------------------------
; EnergyBallShooter_Ai
;
; Energy ball shooter ($16 facing right, $17 facing left; part of a wall
; statue, not drawn or hit): every 32 frames while it is on screen, it
; fires at Link (Enemy_FireAimedBall).
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
EnergyBallShooter_Ai:
    lda     frameCounter            ; $9BDD  every 32 frames,
    and     #$1F                    ; $9BDF
    ora     drawOffscreen+1         ; $9BE1  on screen
    bne     Enemy_FireAimedBall_Done ; $9BE3

; ---------------------------------------------------------------------------
; Enemy_FireAimedBall
;
; Fire an energy ball (projectile type 1, Projectile_Straight_Bank4) from
; enemy x, 4 right of and 5 below its position (plus the carry), if Link
; is on the side it faces and within about 148 pixels.  The speed is by
; his distance, d = (|dx| - 20) / 16 (AimedBallXSpeeds, AimedBallYSpeeds):
; across $06-$13, down $16-$0B, so the ball flies a straight line down at
; him, flatter the further he is.  Otherwise the projectile is cancelled.
;
; In:      x = enemy index
; Out:     carry set if no projectile slot was free
; Status:  confirmed
; ---------------------------------------------------------------------------
Enemy_FireAimedBall:
    jsr     Enemy_FireProjectile    ; $9BE5  take a slot
    bcs     Enemy_FireAimedBall_Done ; $9BE8  none
    sty     temp5                   ; $9BEA
    lda     objFacing+1,x           ; $9BEC  which side is Link on (keeping
    pha                             ; $9BEE  its own facing)?
    jsr     Enemy_FaceLink          ; $9BEF  temp15 = dx
    pla                             ; $9BF2
    sta     objFacing+1,x           ; $9BF3
    iny                             ; $9BF5
    tya                             ; $9BF6
    ldy     temp5                   ; $9BF7
    cmp     objFacing+1,x           ; $9BF9  the side it faces?
    bne     Enemy_CancelAimedBall   ; $9BFB  no: no shot
    sta     a:objFacing+7,y         ; $9BFD
    lda     temp15                  ; $9C00  |dx|
    bpl     @absDx                  ; $9C02
    eor     #$FF                    ; $9C04

@absDx:
    sbc     #$14                    ; $9C06  d = (|dx| - 20) / 16
    lsr     a                       ; $9C08
    lsr     a                       ; $9C09
    lsr     a                       ; $9C0A
    lsr     a                       ; $9C0B
    cmp     #$08                    ; $9C0C  too far (or too near: the
    bcs     Enemy_CancelAimedBall   ; $9C0E  subtraction wraps): no shot
    tax                             ; $9C10
    lda     AimedBallYSpeeds,x      ; $9C11  down, by d
    sta     objYVelocity+7,y        ; $9C14
    lda     AimedBallXSpeeds,x      ; $9C17  across, by d, toward Link
    ldx     objFacing+7,y           ; $9C1A
    dex                             ; $9C1C
    beq     @setXSpeed              ; $9C1D
    eor     #$FF                    ; $9C1F

@setXSpeed:
    sta     a:objXVelocity+7,y      ; $9C21
    ldx     currentObject           ; $9C24
    lda     objY+1,x                ; $9C26  from 5 below,
    adc     #$05                    ; $9C28
    sta     a:objY+7,y              ; $9C2A
    lda     objX+1,x                ; $9C2D  4 right of it
    adc     #$04                    ; $9C2F
    sta     a:objX+7,y              ; $9C31
    lda     objXHi+1,x              ; $9C34
    sta     a:objXHi+7,y            ; $9C36
    lda     #$01                    ; $9C39  projectile type 1
    sta     a:objState+7,y          ; $9C3B

Enemy_FireAimedBall_Done:
    rts                             ; $9C3E

Enemy_CancelAimedBall:
    lda     #$00                    ; $9C3F  free the slot again
    sta     a:objState+7,y          ; $9C41
    rts                             ; $9C44

; ---------------------------------------------------------------------------
; Boss_DrawHpBar
;
; Draw a boss's hit points as a column of 8 sprites at X $10 (sprites
; 48-55, palette 1), from Y $70 up: ceil(hit points / a) full blocks
; (tile $6E) from the bottom, the rest empty ($70).
;
; In:      x = enemy index, a = hit points per block
; Status:  confirmed
; ---------------------------------------------------------------------------
Boss_DrawHpBar:
    sta     temp0                   ; $9C45
    ldy     #$00                    ; $9C47  y = ceil(hp / a)
    lda     enemyHp,x               ; $9C49
    clc                             ; $9C4B

@loop:
    sbc     temp0                   ; $9C4C
    iny                             ; $9C4E
    bcs     @loop                   ; $9C4F
    ldx     #$1C                    ; $9C51  8 sprites, bottom first,
    lda     #$70                    ; $9C53  from Y $70
    sta     temp0                   ; $9C55

Boss_DrawHpBarTile:
    lda     #$70                    ; $9C57  empty,
    dey                             ; $9C59
    bmi     @tile                   ; $9C5A
    lda     #$6E                    ; $9C5C  or full

@tile:
    sta     oamBuffer+193,x         ; $9C5E
    lda     #$01                    ; $9C61  palette 1
; Iron Knuckle tables indexed by ironknuckleKind ($18-$1A) from addresses
; inside this code: IronknuckleGuardMasks ($9C65: 1, 3, 3), the chance the
; shield follows a stroke; IronknuckleRangeOffsets ($9C6C: $1C, $1C, $60)
; and IronknuckleRanges ($9C70: $38, $38, $C0), its distance from Link.
IronknuckleGuardMasks := * + 2
    sta     oamBuffer+194,x         ; $9C63
    lda     #$10                    ; $9C66  X $10
    sta     oamBuffer+195,x         ; $9C68
IronknuckleRangeOffsets := * + 1
    lda     temp0                   ; $9C6B
    sta     oamBuffer+192,x         ; $9C6D

IronknuckleRanges:
    adc     #$F8                    ; $9C70  next up: 8 higher, then 7 (carry)
    sta     temp0                   ; $9C72
    dex                             ; $9C74
    dex                             ; $9C75
    dex                             ; $9C76
    dex                             ; $9C77
    bpl     Boss_DrawHpBarTile      ; $9C78
    ldx     currentObject           ; $9C7A
    rts                             ; $9C7C
    .byte   $01, $03                                                        ; $9C7D

; Iron Knuckle pacing X velocity by facing (1, 2), from the next table.
IronknuckleSpeeds:
    .byte   $03                                                             ; $9C7F

; X velocity toward Link (0 right, 1 left), 1/2 pixel per frame.
SpeedsByFacing_Bank4:
    .byte   $08, $F8                                                        ; $9C80

; Blue Iron Knuckle: thrown sword Y from its Y, by pose / 2 & 1 (4: +$0A
; low; 2: 0 high).
IronknuckleThrowYOffsets:
    .byte   $0A, $00, $1C, $1C, $60                                         ; $9C82
; (unreferenced: $9C87-$9C87, 1 bytes)
    .byte   $50                                                             ; $9C87
    .byte   $38, $38, $C0                                                   ; $9C88
; (unreferenced: $9C8B-$9C8B, 1 bytes)
    .byte   $A0                                                             ; $9C8B

; ---------------------------------------------------------------------------
; Ironknuckle_Ai
;
; Iron Knuckles ($18 orange, $19 red, $1A blue; also the unhorsed
; Rebonack, as blue).  ironknuckleKind indexes the tables.
;
; Engaged when it is on screen (both sprite columns) and Link is level with
; it or up to 41 pixels above it (its Y - his Y = 0-$29): it faces Link and
; walks toward him at 1 pixel per frame until within IronknuckleRanges -
; IronknuckleRangeOffsets: 28 pixels (orange, red) or 96 (blue).  There it
; holds: at Link's X velocity while he walks, else swaying 1/2 pixel per
; frame (frameCounter bit 6), halved unless Link jumps (always halved for
; the blue).  It attacks every 64 frames (enemyAiState), 1 time in 16 the
; next 32 frames sooner, and 4-7 frames after recovering from a hit
; (enemyAiDir, set when its stun timer reaches 2).  An attack: 24 frames of
; wind-up, then 16 of thrust (pose 2 high, pose 4 low), its sword tested
; against Link every frame (Weapon_CheckLink).  The blue Iron Knuckle
; instead throws its sword at the thrust (projectile type 5) and is done.
; The height is half the time random, half the time Link's: high if he
; stands, low if he crouches.  QUIRK: that is where his shield is; the
; rule is the Moblins' (Fighter_StartAttack), whose poses are the other
; way round.
;
; Its shield (guard, enemyAiVar) follows Link's stroke: when he presses B,
; 1 time in 2 (orange) or 3 in 4 (red, blue; IronknuckleGuardMasks), it
; goes to his height (high standing, low crouching); and while he isn't
; level with it, high if he is more than 10 pixels above, else low.
;
; Not engaged, it paces: walks 1/2 pixel per frame for 80 frames, stands
; 80, turns around, and so on.
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
Ironknuckle_Ai:
    jsr     Enemy_Draw              ; $9C8C
    lda     enemyType,x             ; $9C8F  table index: its type,
    cmp     #$18                    ; $9C91
    bcs     @setKind                ; $9C93
    lda     #$1A                    ; $9C95  or blue's (unhorsed Rebonack)

@setKind:
    sta     ironknuckleKind         ; $9C97
    lda     objState+1,x            ; $9C99  attacking?
    beq     @guard                  ; $9C9B
    and     #$01                    ; $9C9D  winding up (odd pose):
    bne     @checkTimer             ; $9C9F  nothing to test
    lda     ironknuckleKind         ; $9CA1  thrusting: the blue one
    cmp     #$1A                    ; $9CA3  throws its sword,
    bne     @testSword              ; $9CA5
    jsr     Enemy_FireProjectile    ; $9CA7  2 px/frame the way it faces
    bcs     @testSword              ; $9CAA  (no slot: thrust instead)
    lda     #$05                    ; $9CAC  projectile type 5
    sta     a:objState+7,y          ; $9CAE
    lda     objState+1,x            ; $9CB1  from Y (pose 2, high) or
    lsr     a                       ; $9CB3  Y + 10 (pose 4, low)
    and     #$01                    ; $9CB4
    tax                             ; $9CB6
    lda     IronknuckleThrowYOffsets,x ; $9CB7
    ldx     currentObject           ; $9CBA
    adc     objY+1,x                ; $9CBC
    sta     a:objY+7,y              ; $9CBE
    bne     @endAttack              ; $9CC1  (always) done

@testSword:
    jsr     Weapon_CheckLink        ; $9CC3  the sword against Link

@checkTimer:
    lda     timerFast+TIMER_ENEMY,x ; $9CC6  pose over?
    bne     @toGuard                ; $9CC9
    inc     objState+1,x            ; $9CCB  next pose
    lda     objState+1,x            ; $9CCD
    cmp     #$03                    ; $9CCF  past 2 or 4: done
    beq     @endAttack              ; $9CD1
    cmp     #$05                    ; $9CD3
    bcs     @endAttack              ; $9CD5
    lda     #$10                    ; $9CD7  thrust for 16 frames
    sta     timerFast+TIMER_ENEMY,x ; $9CD9

@toGuard:
    jmp     @guard                  ; $9CDC

@endAttack:
    lda     #$00                    ; $9CDF
    sta     objState+1,x            ; $9CE1

@guard:
    jsr     Enemy_CheckProjectileHitsSpecial ; $9CE3  its shield (a clink returns)
    jsr     Enemy_UpdateBgCollision ; $9CE6
    ; Enemy_UpdateCommon, without drawing it again.
    ldy     #$01                    ; $9CE9
    inx                             ; $9CEB
    jsr     Obj_ComputeScreenPos    ; $9CEC
    ldx     currentObject           ; $9CEF
    lda     objYHi+1,x              ; $9CF1  fallen below the screen?
    cmp     #$02                    ; $9CF3
    bcc     @onScreen               ; $9CF5
    jmp     Enemy_Despawn           ; $9CF7

@onScreen:
    lda     drawOffscreen+1         ; $9CFA  off screen: no hit tests,
    and     #$FC                    ; $9CFC  despawn if far
    beq     @hitTests               ; $9CFE
    lda     objCollision+1,x        ; $9D00
    and     #$0F                    ; $9D02
    sta     objCollision+1,x        ; $9D04
    jsr     Enemy_DespawnIfFar      ; $9D06
    jmp     @move                   ; $9D09

@hitTests:
    jsr     Enemy_CheckProjectileHits ; $9D0C
    jsr     Enemy_CheckSwordHit     ; $9D0F
    jsr     Enemy_CheckLinkContact  ; $9D12

@move:
    jsr     Enemy_HurtLinkOnContact ; $9D15
    jsr     Enemy_MoveYAndFall      ; $9D18  fall
    lda     objCollision+1,x        ; $9D1B
    and     #$04                    ; $9D1D
    beq     @walk                   ; $9D1F
    jsr     Enemy_Land              ; $9D21

@walk:
    jsr     Enemy_KnockBackOrWalk_Bank4 ; $9D24  move by last frame's velocity
    lda     enemyStunTimer,x        ; $9D27  just recovering from a hit?
    cmp     #$02                    ; $9D2A
    bne     @checkEngaged           ; $9D2C
