; ---------------------------------------------------------------------------
; SkullHead_Init_Bank4B
;
; Spawn routine of skull heads (second palace group), and their respawn:
; as SkullHead_Init, but Y - $24, and flying 1.5 pixels per frame.
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
SkullHead_Init_Bank4B:
    lda     objY                    ; $ACAD  above Link
    sbc     #$24                    ; $ACAF
    sta     objY+1,x                ; $ACB1
    ldy     objFacing               ; $ACB3  the edge he faces
    lda     scrollX                 ; $ACB5
    adc     SkullHeadSpawnX_Bank4B,y ; $ACB8
    sta     objX+1,x                ; $ACBB
    lda     scrollXHi               ; $ACBD
    adc     #$00                    ; $ACC0
    sta     objXHi+1,x              ; $ACC2
    lda     SkullHeadSpeeds_Bank4B,y ; $ACC4  flying inward
    sta     objXVelocity+1,x        ; $ACC7
    jsr     Enemy_StopY             ; $ACC9
    sta     enemyAiState,x          ; $ACCC  (a = 0)
SkullHeadSpawnX_Bank4B := * + 2
    jmp     Enemy_FaceLink          ; $ACCE
    .byte   $EF                                                             ; $ACD1

; As SkullHeadSpeeds: 1.5 pixels per frame inward.
SkullHeadSpeeds_Bank4B:
    .byte   $00, $E8, $18                                                   ; $ACD2

SkullHeadYAccel_Bank4B:
    .byte   $02, $FE                                                        ; $ACD5

; Turning at 2.875 pixels per frame.
SkullHeadMaxYSpeeds_Bank4B:
    .byte   $2E, $D2                                                        ; $ACD7

SkullHead_Ai_Done_Bank4B:
    rts                             ; $ACD9

; ---------------------------------------------------------------------------
; SkullHead_Ai_Bank4B
;
; Blue skull head ($0F, second palace group): as SkullHead_Ai, faster
; across (1.5 pixels per frame), its wave turning at 2.875 pixels per
; frame (92 frames, about 66 pixels deep), starting 4 pixels higher.
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
SkullHead_Ai_Bank4B:
    lda     drawOffscreen+1         ; $ACDA  partly off screen?
    and     #$0C                    ; $ACDC
    beq     @fly                    ; $ACDE
    lda     scrollHeld              ; $ACE0  screen held: wait
    bne     SkullHead_Ai_Done_Bank4B ; $ACE3
    jsr     SkullHead_Init_Bank4B   ; $ACE5  else come again

@fly:
    jsr     Enemy_SkipAiIfStunned   ; $ACE8
    lda     enemyAiState,x          ; $ACEB  accelerate down (even) or
    and     #$01                    ; $ACED  up (odd)
    tay                             ; $ACEF
    lda     objYVelocity+1,x        ; $ACF0
    clc                             ; $ACF3
    adc     SkullHeadYAccel_Bank4B,y ; $ACF4
    sta     objYVelocity+1,x        ; $ACF7
    cmp     SkullHeadMaxYSpeeds_Bank4B,y ; $ACFA  at the top speed: turn
    bne     @move                   ; $ACFD
    inc     enemyAiState,x          ; $ACFF

@move:
    jsr     Enemy_MoveY             ; $AD01
    jsr     Enemy_MoveX             ; $AD04
    jsr     Enemy_UpdateCommon      ; $AD07
    jmp     Enemy_HurtLinkOnContact ; $AD0A

; ---------------------------------------------------------------------------
; Projectile_Mace_Bank4B
;
; Projectile type 6 (the Doom Knocker's mace): flies level; when
; projectileTimer runs out (64 frames, then every 128) it turns around, so
; it comes back past its thrower (it isn't caught) and goes on until it
; leaves the screen or meets Link.
;
; In:      x = projectile index
; Status:  confirmed
; ---------------------------------------------------------------------------
Projectile_Mace_Bank4B:
    lda     projectileTimer,x       ; $AD0D  timer out?
    beq     @turn                   ; $AD10
    dec     projectileTimer,x       ; $AD12
    bpl     Projectile_RestoreX_Bank4B ; $AD15  (from $80: 128 frames)

@turn:
    txa                             ; $AD17  turn the projectile
    clc                             ; $AD18  (object x + 6) around
    adc     #$06                    ; $AD19
    tax                             ; $AD1B
    jsr     Enemy_TurnAround        ; $AD1C
    ldx     currentObject           ; $AD1F
    lda     #$80                    ; $AD21  next turn in 128 frames
    sta     projectileTimer,x       ; $AD23
    jmp     Projectile_RestoreX_Bank4B ; $AD26

; ---------------------------------------------------------------------------
; Projectile_CarockBeam
;
; Projectile type 9 (Wizzrobe's and Carock's beam, second palace group):
; flies level (Projectile_RockBounce_Bank4B), tested against Link's shield
; and body.  Once the reflect spell has sent it back (projectileTimer 0),
; it is tested instead against its thrower (projectileSpeed), while that
; is solid (objState+1): a hit makes a spark and takes 1 hit (Enemy_
; TakeDamage), the only way to hurt a Wizzrobe or Carock.  A Carock it
; kills is kept active as a dying boss (hitbox $FF, stun $7F) for
; Boss_UpdateIntro_Bank4B.
;
; In:      x = projectile index
; Status:  confirmed
; ---------------------------------------------------------------------------
Projectile_CarockBeam:
    lda     projectileTimer,x       ; $AD29  not reflected: fly at Link
    bne     Projectile_RestoreX_Bank4B ; $AD2C
    lda     projectileSpeed,x       ; $AD2E  its thrower,
    tax                             ; $AD31
    stx     swordOwner              ; $AD32
    lda     objState+1,x            ; $AD34  solid,
    beq     Projectile_RestoreX_Bank4B ; $AD36
    lda     enemyActive,x           ; $AD38  and alive?
    cmp     #$01                    ; $AD3A
    bne     Projectile_RestoreX_Bank4B ; $AD3C
    lda     objX+1,x                ; $AD3E  its hitbox
    sbc     scrollX                 ; $AD40
    sta     drawScreenX+1           ; $AD43
    jsr     Enemy_GetHitbox         ; $AD45
    ldy     #$03                    ; $AD48

@loop:
    lda     a:temp4,y               ; $AD4A
    sta     a:temp0,y               ; $AD4D
    dey                             ; $AD50
    bpl     @loop                   ; $AD51
    ldx     currentObject           ; $AD53  against the beam's
    jsr     Projectile_GetHitbox    ; $AD55
    jsr     Hitbox_Overlap          ; $AD58
    bcc     Projectile_RestoreX_Bank4B ; $AD5B
    jsr     Projectile_Spark_Bank4B ; $AD5D  hit: a spark,
    lda     currentObject           ; $AD60
    pha                             ; $AD62
    ldx     swordOwner              ; $AD63  and damage the thrower
    stx     currentObject           ; $AD65
    ldy     #$01                    ; $AD67
    sty     temp11                  ; $AD69
    jsr     Enemy_TakeDamage        ; $AD6B
    pla                             ; $AD6E
    sta     currentObject           ; $AD6F
    ldx     swordOwner              ; $AD71  Carock?
    lda     enemyType,x             ; $AD73
    cmp     #$22                    ; $AD75
    bne     @done                   ; $AD77
