    lda     #$FF                    ; $AD81  as a dying boss
    sta     sramEnemyHitbox+34      ; $AD83
    sta     timerFast+TIMER_ENEMY,x ; $AD86
    lsr     a                       ; $AD89
    sta     enemyStunTimer,x        ; $AD8A

@done:
