Projectile_Done_Bank4B:
    rts                             ; $ADD6

Projectile_DrawAndCheck_Bank4B:
    jsr     Projectile_Draw_Bank4   ; $ADD7
    jsr     DoNothing               ; $ADDA
    jmp     Projectile_CheckLinkAlternate ; $ADDD

@loc_ADE0:
    dec     objXVelocity+7,x        ; $ADE0
    bne     @loc_ADE7               ; $ADE2
    jmp     Projectile_Remove_Bank4B ; $ADE4

@loc_ADE7:
    ldy     objOamOffset+7,x        ; $ADE7
    lda     objY+7,x                ; $ADE9
    sta     temp0                   ; $ADEB
    lda     #$02                    ; $ADED
    sta     temp2                   ; $ADEF
    lsr     a                       ; $ADF1
    sta     temp3                   ; $ADF2
    lsr     a                       ; $ADF4
    sta     drawOffscreen+1         ; $ADF5
    lda     objX+7,x                ; $ADF7
    sbc     scrollX                 ; $ADF9
    sta     temp1                   ; $ADFC
    lda     objXVelocity+7,x        ; $ADFE
    ldx     #$00                    ; $AE00
    cmp     #$08                    ; $AE02
    bcs     @loc_AE08               ; $AE04
    ldx     #$02                    ; $AE06

@loc_AE08:
