HiddenJarOrIronknuckle_Ai:
    lda     drawOffscreen+1         ; $AF61  on screen?
    bne     @done                   ; $AF63
    jsr     Enemy_CheckSwordHit     ; $AF65
    lda     objCollision+1,x        ; $AF68  struck?
    and     #$20                    ; $AF6A
    beq     @done                   ; $AF6C
    lda     #$11                    ; $AF6E  kind $11, a red jar
    sta     enemyAiState,x          ; $AF70
    lda     #$00                    ; $AF72
