    ldy     #$01                    ; $AF76  an item,
    lda     rng+1,x                 ; $AF78
    bpl     @setType                ; $AF7B
    lda     #$18                    ; $AF7D  or half the time a red Iron
    sta     enemyHp,x               ; $AF7F  Knuckle, 24 hit points
