@setType:
    sty     enemyType,x             ; $AF83
    lda     #$08                    ; $AF85  stunned 8 frames
    sta     enemyStunTimer,x        ; $AF87
    lda     objX+1,x                ; $AF8A
    adc     #$03                    ; $AF8C
    sta     objX+1,x                ; $AF8E

