    .byte   $0D, $0F, $11, $13, $15, $17, $A3, $09, $0B, $0D, $0F, $11, $13, $15, $17, $19; $B55F
    .byte   $09, $0B, $0D, $0F, $11, $13, $9F, $A1, $A3, $09, $0B, $0D, $1B, $1D, $1F, $21; $B56F
    .byte   $23, $A3, $29, $2B, $2D, $4E, $50, $62, $7C, $7E                ; $B57F

