; ---------------------------------------------------------------------------
; Gooma_DrawPart
;
; Draw a row of three of Gooma's sprites from GoomaPartTiles + x (the
; outer two swapped and mirrored facing right), in palette temp6.
;
; In:      x = tile index, y = OAM offset
; Status:  confirmed
; ---------------------------------------------------------------------------
Gooma_DrawPart:
    lda     GoomaPartTiles,x        ; $B72D
    sta     oamBuffer+1,y           ; $B730
    lda     GoomaPartTiles+1,x      ; $B733
    sta     oamBuffer+5,y           ; $B736
    lda     GoomaPartTiles+2,x      ; $B739
    sta     oamBuffer+9,y           ; $B73C
    lda     #$00                    ; $B73F
    sta     temp5                   ; $B741
    lda     temp2                   ; $B743
    cmp     #$01                    ; $B745
    bne     @loc_B759               ; $B747
    lda     GoomaPartTiles,x        ; $B749
    sta     oamBuffer+9,y           ; $B74C
    lda     GoomaPartTiles+2,x      ; $B74F
    sta     oamBuffer+1,y           ; $B752
    lda     #$40                    ; $B755
    sta     temp5                   ; $B757

@loc_B759:
    lda     temp5                   ; $B759
    ora     temp6                   ; $B75B
    sta     oamBuffer+2,y           ; $B75D
    sta     oamBuffer+6,y           ; $B760
    sta     oamBuffer+10,y          ; $B763
    lda     drawOffscreen+1         ; $B766
    and     #$08                    ; $B768
    bne     @loc_B771               ; $B76A
    lda     temp0                   ; $B76C
    sta     oamBuffer,y             ; $B76E

@loc_B771:
    lda     drawOffscreen+1         ; $B771
    and     #$04                    ; $B773
    bne     @loc_B77C               ; $B775
    lda     temp0                   ; $B777
    sta     oamBuffer+4,y           ; $B779

@loc_B77C:
    lda     drawOffscreen+1         ; $B77C
    and     #$02                    ; $B77E
    bne     @loc_B787               ; $B780
    lda     temp0                   ; $B782
    sta     oamBuffer+8,y           ; $B784

@loc_B787:
    lda     temp0                   ; $B787
    clc                             ; $B789
    adc     #$10                    ; $B78A
    sta     temp0                   ; $B78C
    lda     temp1                   ; $B78E
    sta     oamBuffer+3,y           ; $B790
    clc                             ; $B793
    adc     #$08                    ; $B794
    sta     oamBuffer+7,y           ; $B796
    clc                             ; $B799
    adc     #$08                    ; $B79A
    sta     oamBuffer+11,y          ; $B79C
    inx                             ; $B79F
    inx                             ; $B7A0
    inx                             ; $B7A1
    tya                             ; $B7A2
    clc                             ; $B7A3
    adc     #$0C                    ; $B7A4
    tay                             ; $B7A6
    rts                             ; $B7A7
; (unreferenced: $B7A8-$B7AF, 8 bytes)
