; ---------------------------------------------------------------------------
; Bubble_Draw
;
; Draw a bubble: a symmetric pair of sprites (SpritePairTiles entry $5A,
; the right one mirrored), its palette cycling every frame (frameCounter
; bits 1-0).
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Bubble_Draw:
    lda     #$02                    ; $B7B0  as if facing left
    sta     temp2                   ; $B7B2
    lda     frameCounter            ; $B7B4  palette 0-3 by the frame
    and     #$03                    ; $B7B6
    sta     temp3                   ; $B7B8
    ldx     #$5A                    ; $B7BA
MagoShotXOffsets := * + 2
    jmp     Sprite_DrawPairFlipped  ; $B7BC
    .byte   $08                                                             ; $B7BF

; Mago's flame: X offset by facing (MagoShotXOffsets, from the jmp's
; high byte: +8 right, -8 left), its high byte, and the speed (3/4 pixel
; per frame).
MagoShotXHiOffsets:
    .byte   $F8, $00                                                        ; $B7C0

MagoShotSpeeds:
    .byte   $FF, $0C, $F4                                                   ; $B7C2

; ---------------------------------------------------------------------------
; Mago_Ai
;
; Wizzrobe ($1D, first palace group; "Mago"): a wizard that comes and goes
; on a 256-frame cycle, enemyAiState counting down:
; - $FF-$E0 (32 frames): blinking in (drawn every other frame);
; - $DF-$C0 (32): solid, hittable and harmful; at $D0 it casts a flame
;   (projectile type 7) at Y $C0, 8 pixels to the side it faces, running
;   along the floor at 3/4 pixel per frame, slowing;
; - $BF-$A0 (32): blinking out;
; - $9F-$00 (160): gone, its X moved each frame to a random place on the
;   screen (scrollX + rng); its Y stays.
; It always faces Link.
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
Mago_Ai:
    jsr     Enemy_FaceLink          ; $B7C5
    dec     enemyAiState,x          ; $B7C8  count down
    lda     enemyAiState,x          ; $B7CA
    cmp     #$E0                    ; $B7CC  $E0+: blinking in
    bcc     @cast                   ; $B7CE
    lsr     a                       ; $B7D0  drawn on odd counts
    bcc     @done                   ; $B7D1
    jmp     Enemy_Draw              ; $B7D3

@cast:
    cmp     #$D0                    ; $B7D6  $D0: cast a flame
    bne     @phase                  ; $B7D8
    jsr     Enemy_DropFlame_Bank4   ; $B7DA
    bcs     @phase                  ; $B7DD  (no slot)
    lda     #$C0                    ; $B7DF  on the floor
    sta     a:objY+7,y              ; $B7E1
    lda     objFacing+1,x           ; $B7E4  the way it faces
    sta     a:objFacing+7,y         ; $B7E6
    tax                             ; $B7E9
    lda     a:objX+7,y              ; $B7EA  8 pixels to that side
    adc     MagoShotXOffsets,x      ; $B7ED
    sta     a:objX+7,y              ; $B7F0
    lda     a:objXHi+7,y            ; $B7F3
    adc     MagoShotXHiOffsets,x    ; $B7F6
    sta     a:objXHi+7,y            ; $B7F9
    lda     MagoShotSpeeds,x        ; $B7FC  3/4 px/frame
    sta     a:objXVelocity+7,y      ; $B7FF
    sta     projectileSpeed,y       ; $B802
    ldx     currentObject           ; $B805

@phase:
    lda     enemyAiState,x          ; $B807  below $A0: gone
    cmp     #$A0                    ; $B809
    bcc     @move                   ; $B80B
    cmp     #$C0                    ; $B80D  $C0-$DF: solid
    bcs     @solid                  ; $B80F
    lsr     a                       ; $B811  $A0-$BF: blinking out,
    bcc     @draw                   ; $B812  drawn on even counts

@done:
    rts                             ; $B814

@solid:
    jsr     Enemy_UpdateCommon      ; $B815
    jmp     Enemy_HurtLinkOnContact ; $B818

@draw:
    jmp     Enemy_Draw              ; $B81B

@move:
    lda     scrollX                 ; $B81E  somewhere on screen
    adc     rng+1,x                 ; $B821
    sta     objX+1,x                ; $B824
    lda     scrollXHi               ; $B826
    adc     #$00                    ; $B829
    sta     objXHi+1,x              ; $B82B
    lda     #$00                    ; $B82D
    sta     enemyStunTimer,x        ; $B82F
    rts                             ; $B832

; ---------------------------------------------------------------------------
; SkullHead_Draw
;
; Draw a skull head: a pair of sprites from sramEnemyTiles entry $82, the
; facing flipped (the tiles face the other way).
;
; Status:  confirmed
; ---------------------------------------------------------------------------
SkullHead_Draw:
    ldx     #$82                    ; $B833
    lda     temp2                   ; $B835  flip the facing
    eor     #$03                    ; $B837
    sta     temp2                   ; $B839
    jmp     Sprite_DrawEnemyPairKeepX ; $B83B

; ---------------------------------------------------------------------------
; HiddenJar_Ai
;
; Hidden jar ($05, first palace group): invisible and still until Link's
; sword strikes it, when it becomes a red jar (an item, type $01, kind $11)
; 3 pixels right, which falls and is taken by another stroke.
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
HiddenJar_Ai:
    lda     drawOffscreen+1         ; $B83E  on screen?
    bne     @done                   ; $B840
    jsr     Enemy_CheckSwordHit     ; $B842
    lda     objCollision+1,x        ; $B845  struck?
    and     #$20                    ; $B847
    beq     @done                   ; $B849
    lda     #$11                    ; $B84B  a red jar
    sta     enemyAiState,x          ; $B84D
    lda     #$01                    ; $B84F  type $01, an item
    sta     enemyType,x             ; $B851
    sta     enemyHp,x               ; $B853
    lsr     enemyStunTimer,x        ; $B855
    lda     objX+1,x                ; $B858
    adc     #$03                    ; $B85A
    sta     objX+1,x                ; $B85C

@done:
    rts                             ; $B85E

; Wolf heads: X velocity and spawn X offset by side (0 left edge: +8,
; 1 right edge: -8); also the Y velocity of their steps (0 down, 1 up).
FlyerSpeeds_Bank4:
    .byte   $08, $F8                                                        ; $B85F

; ---------------------------------------------------------------------------
; WolfHeadGenerator_Ai
;
; Wolf head generator ($1B): every 128 frames (frameCounter $00, $80),
; while the screen follows Link (scrollHeld 0), launch a wolf head
; (Enemy_SpawnFlyer_Bank4).
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
WolfHeadGenerator_Ai:
    lda     frameCounter            ; $B861  bits 6-0 all 0,
    asl     a                       ; $B863
    ora     scrollHeld              ; $B864  and the screen following Link?
    bne     Enemy_SpawnFlyerFail_Bank4 ; $B867

; ---------------------------------------------------------------------------
; Enemy_SpawnFlyer_Bank4
;
; Put a wolf head ($1C) in a free enemy slot (from 5 down): 2 hit points,
; at Link's Y - 2 (- 3 with the carry), at the edge of the screen he is
; heading for (the right edge, flying left, if he holds Right; the left
; if Left; either at random if neither), flying inward at 1/2 pixel per
; frame (FlyerSpeeds_Bank4), with no list entry and enemyAiState $FF.
; Enemy_InitFlyer_Bank4 does it in slot x.
;
; Out:     carry set if no slot was free; temp0 = the slot
; Status:  confirmed
; ---------------------------------------------------------------------------
Enemy_SpawnFlyer_Bank4:
    ldx     #$05                    ; $B869  find a free slot

@loop:
    lda     enemyActive,x           ; $B86B
    beq     Enemy_InitFlyer_Bank4   ; $B86D
    dex                             ; $B86F
    bpl     @loop                   ; $B870

Enemy_SpawnFlyerFail_Bank4:
    ldx     currentObject           ; $B872  none (or not now)
    sec                             ; $B874
    rts                             ; $B875

Enemy_InitFlyer_Bank4:
    lda     #$02                    ; $B876  2 hit points
    sta     enemyHp,x               ; $B878
    lsr     a                       ; $B87A
    sta     enemyActive,x           ; $B87B  active
    sta     objYHi+1,x              ; $B87D
    lsr     a                       ; $B87F
    sta     enemyStunTimer,x        ; $B880
    lda     objY                    ; $B883  at Link's height
    sbc     #$02                    ; $B885
    sta     objY+1,x                ; $B887
    lda     #$1C                    ; $B889  a wolf head
    sta     enemyType,x             ; $B88B
    lda     joypadHeld              ; $B88D  Right (1) or Left (2) held?
    and     #$03                    ; $B88F
    bne     @side                   ; $B891
    lda     rng+1,x                 ; $B893  neither: at random

@side:
    and     #$01                    ; $B896  y = 1: right edge, 0: left
    tay                             ; $B898
    lda     scrollX                 ; $B899  X = left edge + $08 or + $F8
    adc     FlyerSpeeds_Bank4,y     ; $B89C
    sta     objX+1,x                ; $B89F
    lda     scrollXHi               ; $B8A1
    adc     #$00                    ; $B8A4
    sta     objXHi+1,x              ; $B8A6
    lda     FlyerSpeeds_Bank4,y     ; $B8A8  flying inward, 1/2 px/frame
    sta     objXVelocity+1,x        ; $B8AB
    lda     #$FF                    ; $B8AD  no list entry
    sta     enemySramIndex,x        ; $B8AF
    sta     enemyAiState,x          ; $B8B1
    iny                             ; $B8B3  facing its way
    sty     objFacing+1,x           ; $B8B4
    stx     temp0                   ; $B8B6
    ldx     currentObject           ; $B8B8
    rts                             ; $B8BA

; ---------------------------------------------------------------------------
; WolfHead_Ai
;
; Wolf head ($1C): a flying head that crosses the screen in steps.
; enemyAiState counts frames: 32 frames it flies across at 1/2 pixel per
; frame, the next 32 it moves straight down 16 pixels, then across, then
; up 16 (bit 5: moving vertically; bit 6: up), and so on.  At the start of
; each 64 (count bits 5-0 all 0), if it faces Link, it fires an energy
; ball straight ahead (projectile type 1, 2 pixels per frame,
; Enemy_FireProjectile).  It ignores the background and never turns.
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
WolfHead_Ai:
    jsr     Enemy_UpdateCommon      ; $B8BB  draw, hit tests (no background)
    jsr     Enemy_HurtLinkOnContact ; $B8BE
    inc     enemyAiState,x          ; $B8C1  count frames
    lda     enemyAiState,x          ; $B8C3
    lsr     a                       ; $B8C5  carry = bit 5
    lsr     a                       ; $B8C6
    lsr     a                       ; $B8C7
    lsr     a                       ; $B8C8
    lsr     a                       ; $B8C9
    lsr     a                       ; $B8CA
    bcs     @vertical               ; $B8CB  second 32 of 64: up or down
    lda     enemyAiState,x          ; $B8CD  start of a 64?
    and     #$3F                    ; $B8CF
    bne     @moveX                  ; $B8D1
    lda     objFacing+1,x           ; $B8D3  facing Link (keeping its
    sta     temp5                   ; $B8D5  facing)?
    pha                             ; $B8D7
    jsr     Enemy_FaceLink          ; $B8D8
    iny                             ; $B8DB
    cpy     temp5                   ; $B8DC
    bne     @restoreFacing          ; $B8DE  no
    jsr     Enemy_FireProjectile    ; $B8E0  yes: fire straight ahead
    bcs     @restoreFacing          ; $B8E3
    lda     #$01                    ; $B8E5  projectile type 1
    sta     a:objState+7,y          ; $B8E7

@restoreFacing:
    pla                             ; $B8EA
    sta     objFacing+1,x           ; $B8EB

@moveX:
    jmp     Enemy_MoveX             ; $B8ED  across, 1/2 px/frame

@vertical:
    and     #$01                    ; $B8F0  bit 6: 0 down, 1 up
    tay                             ; $B8F2
    lda     FlyerSpeeds_Bank4,y     ; $B8F3  1/2 px/frame
    sta     objYVelocity+1,x        ; $B8F6
    jmp     Enemy_MoveY             ; $B8F9

; ---------------------------------------------------------------------------
; EnergyBallShooter_Init
;
; Spawn routine of energy ball shooters: facing by type ($16 - $15 = 1
; right, $17 - $15 = 2 left).
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
EnergyBallShooter_Init:
    lda     enemyType,x             ; $B8FC
    sec                             ; $B8FE
    sbc     #$15                    ; $B8FF
    sta     objFacing+1,x           ; $B901
    rts                             ; $B903

; ---------------------------------------------------------------------------
; WolfHead_Draw
;
; Draw a wolf head: a pair of sprites from sramEnemyTiles entry $16, facing
; its objFacing (Ironknuckle_DrawPair).
;
; Status:  confirmed
; ---------------------------------------------------------------------------
WolfHead_Draw:
    ldx     #$16                    ; $B904  entry $16
    jmp     Ironknuckle_DrawPair    ; $B906

; ---------------------------------------------------------------------------
; OrangeMoa_Ai
;
; Orange Moa ($07): a flying eye that comes in from the side Link faces, at
; Y $7D, 2 pixels per frame, for 16 frames (80 if Link stands still), then
; rises 1 pixel per frame for 64 frames while its X velocity swings by
; 1/16 per frame the other way, turning it back; it flies out the way it
; came at about 2 pixels per frame, dropping flames, and 191 frames after
; leaving the screen comes again.  It bobs (Y velocity +-4/16, 16 frames
; each) the whole time it is out.  enemyAiState & 3: 0 waiting, 1 coming
; in, 2 rising, 3 flying out.
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
OrangeMoa_Ai:
    lda     enemyAiState,x          ; $B909  out (state 1-3)?
    and     #$03                    ; $B90B
    beq     @state                  ; $B90D
    ldy     #$04                    ; $B90F  bob: +-4/16 px/frame,
    lda     frameCounter            ; $B911  16 frames each
    and     #$10                    ; $B913
    bne     @bob                    ; $B915
    ldy     #$FC                    ; $B917

@bob:
    tya                             ; $B919
    sta     objYVelocity+1,x        ; $B91A
    jsr     Enemy_MoveY             ; $B91D
    jsr     Enemy_MoveX             ; $B920
    jsr     Enemy_UpdateWithBg      ; $B923
    jsr     Enemy_HurtLinkOnContact ; $B926

@state:
    lda     enemyAiState,x          ; $B929
    and     #$03                    ; $B92B
    jsr     JumpTable               ; $B92D
; (inline jump table)
    .word   OrangeMoa_Appear        ; $B930
    .word   OrangeMoa_Wait          ; $B932
    .word   OrangeMoa_Rise          ; $B934
OrangeMoaSpawnX := * + 1
    .word   OrangeMoa_Fly           ; $B936
    .byte   $F0                                                             ; $B938

OrangeMoaSpeeds:
    .byte   $00, $E0, $20                                                   ; $B939

; ---------------------------------------------------------------------------
; OrangeMoa_Appear
;
; OrangeMoa state 0: when its timer ends, appear at the edge of the screen
; Link faces (OrangeMoaSpawnX: $F0 right, 0 left) at Y $7D, flying inward
; at 2 pixels per frame (OrangeMoaSpeeds), for 16 frames, or 80 while
; Link stands.
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
OrangeMoa_Appear:
    lda     timerFast+TIMER_ENEMY,x ; $B93C  wait for the timer
    bne     @done                   ; $B93F
    ldy     objFacing               ; $B941  the edge Link faces
    lda     scrollX                 ; $B943
    adc     OrangeMoaSpawnX,y       ; $B946
    sta     objX+1,x                ; $B949
    lda     scrollXHi               ; $B94B
    adc     #$00                    ; $B94E
    sta     objXHi+1,x              ; $B950
    lda     OrangeMoaSpeeds,y       ; $B952  flying inward
    sta     objXVelocity+1,x        ; $B955
    lda     #$7D                    ; $B957
    sta     objY+1,x                ; $B959
    sty     objState+1,x            ; $B95B  the side (for OrangeMoa_Rise)
    sty     objFacing+1,x           ; $B95D
    lda     #$10                    ; $B95F  16 frames,
    ldy     objXVelocity            ; $B961
    bne     @setTimer               ; $B963
    lda     #$50                    ; $B965  80 if Link stands

@setTimer:
    sta     timerFast+TIMER_ENEMY,x ; $B967
    inc     enemyAiState,x          ; $B96A

@done:
    rts                             ; $B96C

; ---------------------------------------------------------------------------
; OrangeMoa_Wait
;
; State 1: wait for the timer, then 64 frames of rising.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
OrangeMoa_Wait:
    lda     timerFast+TIMER_ENEMY,x ; $B96D
    bne     @done                   ; $B970
    lda     #$40                    ; $B972
    sta     timerFast+TIMER_ENEMY,x ; $B974
    inc     enemyAiState,x          ; $B977

@done:
    rts                             ; $B979
; The rts byte is also the base of the table OrangeMoaAccel (entry 0 is the rts).
OrangeMoaAccel := @done
    .byte   $01, $FF                                                        ; $B97A

; ---------------------------------------------------------------------------
; OrangeMoa_Rise
;
; State 2: rise 1 pixel per frame while the timer runs (64 frames), the X
; velocity moving 1/16 per frame toward the side it came from
; (OrangeMoaAccel by objState+1): from -2 to +2 or back.
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
OrangeMoa_Rise:
    lda     timerFast+TIMER_ENEMY,x ; $B97C
    beq     @next                   ; $B97F
    dec     objY+1,x                ; $B981  up 1 px
    ldy     objState+1,x            ; $B983  turn back
    lda     objXVelocity+1,x        ; $B985
    clc                             ; $B987
    adc     OrangeMoaAccel,y        ; $B988
    sta     objXVelocity+1,x        ; $B98B
    rts                             ; $B98D

@next:
    inc     enemyAiState,x          ; $B98E  fly out
    rts                             ; $B990

; ---------------------------------------------------------------------------
; OrangeMoa_Fly
;
; State 3: fly on, dropping a flame on frames where frameCounter & $2F is
; 0 (2 in each 64) unless touching anything; once off screen, wait 191
; frames (state 4, which is 0 again) and come again.
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
OrangeMoa_Fly:
    lda     drawOffscreen+1         ; $B991  off screen?
    beq     @maybeDrop              ; $B993
    lda     #$BF                    ; $B995  wait 191 frames
    sta     timerFast+TIMER_ENEMY,x ; $B997
    inc     enemyAiState,x          ; $B99A

@maybeDrop:
    lda     frameCounter            ; $B99C
    and     #$2F                    ; $B99E
    ora     objCollision+1,x        ; $B9A0
    bne     Enemy_DropFlame_Done_Bank4 ; $B9A2

; ---------------------------------------------------------------------------
; Enemy_DropFlame_Bank4
;
; Drop a flame (projectile type 7: no speed, burns for 255 frames) from
; enemy x.
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
Enemy_DropFlame_Bank4:
    jsr     Enemy_FireProjectile    ; $B9A4
    bcs     Enemy_DropFlame_Done_Bank4 ; $B9A7  (no slot)
    lda     #$07                    ; $B9A9  a flame
    sta     a:objState+7,y          ; $B9AB
    lda     #$FF                    ; $B9AE  255 frames
    sta     projectileTimer,y       ; $B9B0
    lda     #$00                    ; $B9B3  no speed
    sta     projectileSpeed,y       ; $B9B5
    sta     a:objXVelocity+7,y      ; $B9B8
    sta     objYVelocity+7,y        ; $B9BB

Enemy_DropFlame_Done_Bank4:
    rts                             ; $B9BE

; ---------------------------------------------------------------------------
; AcidDripper_Ai
;
; Acid dripper ($0D): a fixed spout in the ceiling.  Every 64 frames it
; drips a drop of acid (projectile type 8) from X + 4, Y + 18, with no
; speed; projectileTimer holds rng & 7, and a drop with 0 (1 in 8) becomes
; a Bot where it lands (Projectile_AcidDrop_Bank4).
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
AcidDripper_Ai:
    jsr     Enemy_Draw              ; $B9BF
    inc     enemyAiState,x          ; $B9C2  every 64 frames
    lda     enemyAiState,x          ; $B9C4
    and     #$3F                    ; $B9C6
    bne     @done                   ; $B9C8
    jsr     Enemy_FireProjectile    ; $B9CA
    bcs     @done                   ; $B9CD  (no slot)
    lda     #$08                    ; $B9CF  a drop of acid
    sta     a:objState+7,y          ; $B9D1
    lda     objX+1,x                ; $B9D4  at X + 4,
    adc     #$04                    ; $B9D6
    sta     a:objX+7,y              ; $B9D8
    lda     a:objY+7,y              ; $B9DB  Y + 18
    adc     #$12                    ; $B9DE
    sta     a:objY+7,y              ; $B9E0
    lda     #$00                    ; $B9E3  falling from rest
    sta     a:objXVelocity+7,y      ; $B9E5
    sta     objYVelocity+7,y        ; $B9E8
    lda     rng+1,x                 ; $B9EB  0 (1 in 8): a Bot
    and     #$07                    ; $B9EE
    sta     projectileTimer,y       ; $B9F0

@done:
    rts                             ; $B9F3

; ---------------------------------------------------------------------------
; SkullHead_Init
;
; Spawn routine of skull heads, and their respawn: about 32 pixels above
; Link (Y - $20), at the edge of the screen he faces (SkullHeadSpawnX:
; $EF right, 0 left), flying inward 1 pixel per frame (SkullHeadSpeeds),
; Y velocity 0, state 0.
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
SkullHead_Init:
    lda     objY                    ; $B9F4  above Link
    sbc     #$20                    ; $B9F6
    sta     objY+1,x                ; $B9F8
    ldy     objFacing               ; $B9FA  the edge he faces
    lda     scrollX                 ; $B9FC
    adc     SkullHeadSpawnX,y       ; $B9FF
    sta     objX+1,x                ; $BA02
    lda     scrollXHi               ; $BA04
    adc     #$00                    ; $BA07
    sta     objXHi+1,x              ; $BA09
    lda     SkullHeadSpeeds,y       ; $BA0B  flying inward
    sta     objXVelocity+1,x        ; $BA0E
    jsr     Enemy_StopY             ; $BA10
    sta     enemyAiState,x          ; $BA13  (a = 0)
SkullHeadSpawnX := * + 2
    jmp     Enemy_FaceLink          ; $BA15
    .byte   $EF                                                             ; $BA18

; Skull head X velocity by Link's facing: 1 pixel per frame inward.
SkullHeadSpeeds:
    .byte   $00, $F0, $10                                                   ; $BA19

; Skull head Y acceleration by enemyAiState & 1, down then up.
SkullHeadYAccel:
    .byte   $02, $FE                                                        ; $BA1C

; ... until the Y velocity reaches this (3 pixels per frame), state + 1.
SkullHeadMaxYSpeeds:
    .byte   $30, $D0                                                        ; $BA1E

; ---------------------------------------------------------------------------
; SkullHead_Ai
;
; Blue skull head ($0A, first palace group): flies across 1 pixel per
; frame in a wave: its Y velocity swings between +3 and -3 by 2/16 per
; frame, so it dives 72 pixels below its start (passing through Link) and
; climbs back, every 96 frames.  When partly off screen it starts again
; ahead of Link (SkullHead_Init), unless the screen is held at an area
; end, when it waits.
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
SkullHead_Ai:
    lda     drawOffscreen+1         ; $BA20  partly off screen?
    and     #$0C                    ; $BA22
    beq     @fly                    ; $BA24
    lda     scrollHeld              ; $BA26  screen held: wait
    bne     @done                   ; $BA29
    jsr     SkullHead_Init          ; $BA2B  else come again

@fly:
    jsr     Enemy_SkipAiIfStunned   ; $BA2E
    lda     enemyAiState,x          ; $BA31  accelerate down (even) or
    and     #$01                    ; $BA33  up (odd)
    tay                             ; $BA35
    lda     objYVelocity+1,x        ; $BA36
    clc                             ; $BA39
    adc     SkullHeadYAccel,y       ; $BA3A
    sta     objYVelocity+1,x        ; $BA3D
    cmp     SkullHeadMaxYSpeeds,y   ; $BA40  at 3 px/frame: turn
    bne     @move                   ; $BA43
    inc     enemyAiState,x          ; $BA45

@move:
    jsr     Enemy_MoveY             ; $BA47
    jsr     Enemy_MoveX             ; $BA4A
    jsr     Enemy_UpdateCommon      ; $BA4D
    jmp     Enemy_HurtLinkOnContact ; $BA50

@done:
    rts                             ; $BA53
; The rts byte is also the base of the table BossPaceSpeeds (entry 0 is the rts).
BossPaceSpeeds := @done

; Hammer Thrower pacing X velocity by enemyAiState bit 6: right, left.
HammerThrowerSpeeds:
    .byte   $08, $F8, $08                                                   ; $BA54

; ---------------------------------------------------------------------------
; HammerThrower_Ai
;
; Hammer Thrower ($1E, first palace group): paces 1/2 pixel per frame, 64
; frames right and 64 left (by enemyAiState bit 6), facing Link (turned
; every 16 frames); jumps when frameCounter is 0 (Y velocity -3); and
; every 32 frames, but not in the last 40 of each 256 (enemyAiState
; $D8+), raises a hammer for 15 frames (Enemy_StartSwing, drawn in its
; hand) and throws it: projectile type 6, 1 pixel per frame the way it
; faces, up at -$2B, falling under gravity (Projectile_Fall_Bank4).
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
HammerThrower_Ai:
    lda     frameCounter            ; $BA57  every 256 frames:
    bne     @swing                  ; $BA59
    lda     #$D0                    ; $BA5B  jump
    sta     objYVelocity+1,x        ; $BA5D

@swing:
    lda     enemyAiState,x          ; $BA60  every 32 frames, but not
    cmp     #$D8                    ; $BA62  past $D8:
    bcs     @throw                  ; $BA64
    and     #$1F                    ; $BA66
    bne     @throw                  ; $BA68
    jsr     Enemy_StartSwing        ; $BA6A  raise a hammer (15 frames)

@throw:
    lda     timerFast+TIMER_ENEMY,x ; $BA6D  raised long enough?
    cmp     #$01                    ; $BA70
    bne     @pace                   ; $BA72
    sta     objState+1,x            ; $BA74  (pose 1)
    jsr     Enemy_FireProjectile    ; $BA76
    bcs     @pace                   ; $BA79  (no slot)
    lda     #$06                    ; $BA7B  a hammer
    sta     a:objState+7,y          ; $BA7D
    lda     #$D5                    ; $BA80  thrown up
    sta     objYVelocity+7,y        ; $BA82
    lda     a:objXVelocity+7,y      ; $BA85  at half speed (keeping the
    asl     a                       ; $BA88  sign): 1 px/frame
    lda     a:objXVelocity+7,y      ; $BA89
    ror     a                       ; $BA8C
    sta     a:objXVelocity+7,y      ; $BA8D

@pace:
    lda     enemyAiState,x          ; $BA90  bit 6: right or left
    asl     a                       ; $BA92
    asl     a                       ; $BA93
    lda     #$00                    ; $BA94
    rol     a                       ; $BA96
    tay                             ; $BA97
    lda     HammerThrowerSpeeds,y   ; $BA98
    sta     objXVelocity+1,x        ; $BA9B
    jsr     Enemy_MoveYAndFall      ; $BA9D
    inc     enemyAiState,x          ; $BAA0
    jsr     Enemy_UpdateBgCollision ; $BAA2
    lda     objCollision+1,x        ; $BAA5  on the floor: land
    and     #$04                    ; $BAA7
    beq     @walk                   ; $BAA9
    jsr     Enemy_Land              ; $BAAB

@walk:
    jsr     Enemy_KnockBackOrWalk_Bank4 ; $BAAE
    jsr     Enemy_UpdateWithBg      ; $BAB1
    jsr     Enemy_HurtLinkOnContact ; $BAB4
    lda     frameCounter            ; $BAB7  every 16 frames,
    and     #$0F                    ; $BAB9
    bne     @done                   ; $BABB
    jmp     Enemy_FaceLink          ; $BABD  face Link

@done:
    rts                             ; $BAC0
; The rts byte is also the base of the table HelmetheadHeadLaunchSpeeds
; (entry 0 is the rts): a knocked-off helmet's X velocity by Helmethead's
; facing, backward: $F0 facing right, $10 facing left.
HelmetheadHeadLaunchSpeeds := @done
    .byte   $F0                                                             ; $BAC1
    .byte   $10                                                             ; $BAC2

; ---------------------------------------------------------------------------
; Helmethead_Ai
;
; Helmethead ($21, palace 2 boss; in palace 5, where currentRegion isn't 0,
; the same type is Gooma, Gooma_Ai).  He paces like Horsehead (Boss_Pace,
; 6 hit points per bar block), fires an energy ball every 128 frames
; (projectile type 2, from 8 pixels higher, sinking at 2/16 pixel per
; frame), and has a guard (guard 2): only strokes at his head get through.
; Each such hit, while helmetheadHitDelay is 0 and he still has a helmet
; (objState+1 counts the lost ones, up to 2), knocks a helmet off: a
; HelmetheadHead ($22) is launched from 12 pixels above him, up at -3 and
; 1 pixel per frame backward, and the delay is set to 16 (64 frames).
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
Helmethead_Ai:
    lda     currentRegion           ; $BAC3  palace 5: Gooma
    beq     @helmethead             ; $BAC6
    jmp     Gooma_Ai                ; $BAC8

@helmethead:
    jsr     Boss_UpdateIntro        ; $BACB
    jsr     Boss_UpdateCommon       ; $BACE
    lda     #$06                    ; $BAD1  6 hit points per block
    ldy     currentRegion           ; $BAD3  (18 elsewhere: never)
    beq     @pace                   ; $BAD6
; (code below not executed in the test movies)
    lda     #$12                    ; $BAD8
; (end of code not executed in the test movies)

@pace:
    jsr     Boss_Pace               ; $BADA
    lda     frameCounter            ; $BADD  every 128 frames:
    and     #$7F                    ; $BADF
    bne     @helmet                 ; $BAE1
; (code below not executed in the test movies)
    jsr     Enemy_FireProjectile    ; $BAE3  an energy ball
    bcs     @helmet                 ; $BAE6
    lda     #$02                    ; $BAE8
    sta     a:objState+7,y          ; $BAEA
    lda     a:objY+7,y              ; $BAED  8 pixels higher,
    sbc     #$08                    ; $BAF0
    sta     a:objY+7,y              ; $BAF2
    lda     #$02                    ; $BAF5  sinking slowly
    sta     objYVelocity+7,y        ; $BAF7
; (end of code not executed in the test movies)

@helmet:
    lda     helmetheadHitDelay      ; $BAFA  just lost one?
    bne     @countDown              ; $BAFD
    lda     objCollision+1,x        ; $BAFF  struck by the sword,
    and     #$20                    ; $BB01
    beq     @done                   ; $BB03
    lda     objState+1,x            ; $BB05  with a helmet left?
    cmp     #$02                    ; $BB07
    beq     @done                   ; $BB09
    lda     #$10                    ; $BB0B  64 frames before the next
    sta     helmetheadHitDelay      ; $BB0D
    jsr     Enemy_SpawnFlyer_Bank4  ; $BB10  a free slot (temp0)?
    bcs     @done                   ; $BB13
    ldy     temp0                   ; $BB15
    lda     objY+1,x                ; $BB17  the helmet, 12 above him
    sbc     #$0C                    ; $BB19
    sta     a:objY+1,y              ; $BB1B
    lda     objX+1,x                ; $BB1E
    sta     a:objX+1,y              ; $BB20
    lda     objXHi+1,x              ; $BB23
    sta     a:objXHi+1,y            ; $BB25
    lda     objFacing+1,x           ; $BB28
    sta     a:objFacing+1,y         ; $BB2A
    lda     #$22                    ; $BB2D  type $22
    sta     a:enemyType,y           ; $BB2F
    lda     #$00                    ; $BB32
    sta     enemyAiVar,y            ; $BB34
    sta     a:enemyAiState,y        ; $BB37
    lda     #$D0                    ; $BB3A  flung up at -3
    sta     objYVelocity+1,y        ; $BB3C
    sta     a:enemyHp,y             ; $BB3F
    lda     objFacing+1,x           ; $BB42  and backward, 1 px/frame
    tax                             ; $BB44
    lda     HelmetheadHeadLaunchSpeeds,x ; $BB45
    sta     a:objXVelocity+1,y      ; $BB48
    ldx     currentObject           ; $BB4B
    lda     objState+1,x            ; $BB4D  which helmet (0, 1)
    sta     a:objState+1,y          ; $BB4F
    inc     objState+1,x            ; $BB52  one more lost

@done:
    rts                             ; $BB54

@countDown:
    lda     frameCounter            ; $BB55  every 4 frames
    and     #$03                    ; $BB57
    bne     @done2                  ; $BB59
    dec     helmetheadHitDelay      ; $BB5B

@done2:
    rts                             ; $BB5E

; ---------------------------------------------------------------------------
; HorseHead_Ai
;
; Horsehead ($20, palace 1 boss): Boss_UpdateIntro, Boss_UpdateCommon (his
; guard, 2, turns aside strokes below his head), his mace tested against
; Link's body (Weapon_CheckLinkBody), the swing (HorseHead_Attack), and
; Boss_Pace with 4 hit points per bar block.
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
HorseHead_Ai:
    jsr     Boss_UpdateIntro        ; $BB5F
    jsr     Boss_UpdateCommon       ; $BB62
    jsr     Weapon_CheckLinkBody    ; $BB65  the mace
    jsr     HorseHead_Attack        ; $BB68
    lda     frameCounter            ; $BB6B  (no effect)
    bne     @hpPerBlock             ; $BB6D

@hpPerBlock:
    lda     #$04                    ; $BB6F  4 hit points per block

; ---------------------------------------------------------------------------
; Boss_Pace
;
; Horsehead's and Helmethead's movement; also draws the hit point bar (a
; hit points per block).  The boss turns toward Link only every 32 frames
; (and Horsehead not while swinging).  enemyAiState: bits 6-0 count
; frames / 2 of walking, bit 7 set to back away from Link, clear to come
; toward him, at 1/2 pixel per frame (BossPaceSpeeds) -- but only while
; facing him.  At 96 pixels or more from Link the count restarts toward
; him (Boss_ResetState).  Nearer, Boss_ChooseAttack.
;
; In:      x = enemy index, a = hit points per bar block
; Status:  confirmed
; ---------------------------------------------------------------------------
Boss_Pace:
    jsr     Boss_DrawHpBar          ; $BB71
    lda     objFacing+1,x           ; $BB74
    pha                             ; $BB76
    jsr     Enemy_FaceLink          ; $BB77  temp1 = the facing toward Link
    iny                             ; $BB7A
    sty     temp1                   ; $BB7B
    pla                             ; $BB7D
    sta     temp0                   ; $BB7E
    lda     enemyType,x             ; $BB80  Horsehead swinging:
    cmp     #$20                    ; $BB82  keep his facing
    bne     @turn                   ; $BB84
    lda     objState+1,x            ; $BB86
    bne     @keepFacing             ; $BB88

@turn:
    lda     frameCounter            ; $BB8A  turn only every 32 frames
    and     #$1F                    ; $BB8C
    beq     @walk                   ; $BB8E

@keepFacing:
    lda     temp0                   ; $BB90
    sta     objFacing+1,x           ; $BB92

@walk:
    lda     #$00                    ; $BB94  standing,
    sta     objXVelocity+1,x        ; $BB96
    lda     enemyAiState,x          ; $BB98  unless counting
    asl     a                       ; $BB9A
    beq     @distance               ; $BB9B
    bcc     @toward                 ; $BB9D  bit 7: away from Link
    iny                             ; $BB9F

@toward:
    lda     temp1                   ; $BBA0  only while facing him
    cmp     objFacing+1,x           ; $BBA2
    bne     Boss_ResetState_Done    ; $BBA4
    lda     BossPaceSpeeds,y        ; $BBA6
    sta     objXVelocity+1,x        ; $BBA9
    lda     frameCounter            ; $BBAB  count every other frame
    lsr     a                       ; $BBAD
    bcc     @distance               ; $BBAE
    dec     enemyAiState,x          ; $BBB0

@distance:
    lda     temp15                  ; $BBB2  |dx|
    bpl     @abs                    ; $BBB4
    eor     #$FF                    ; $BBB6

@abs:
    cmp     #$60                    ; $BBB8  near (under 96)?
    bcc     Boss_ChooseAttack       ; $BBBA

; ---------------------------------------------------------------------------
; Boss_ResetState
;
; Restart the pacing count toward Link: enemyAiState bit 7 clear, bit 4
; set (at least 32 frames).
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
Boss_ResetState:
    lda     enemyAiState,x          ; $BBBC
    and     #$7F                    ; $BBBE
    ora     #$10                    ; $BBC0
    sta     enemyAiState,x          ; $BBC2

Boss_ResetState_Done:
    rts                             ; $BBC4

; Boss_ChooseAttack: a = |dx| under 96.  At 32 or more: every 64 frames, 3
; times in 4, come toward Link again.  Under 32: Horsehead, facing Link
; and not swinging, swings 1 time in 8 each frame; and once the count is
; out, 1 time in 8 each frame a new count starts, toward or away at random.
Boss_ChooseAttack:
    cmp     #$20                    ; $BBC5  under 32?
    bcc     @near                   ; $BBC7
    lda     frameCounter            ; $BBC9  every 64 frames,
    and     #$3F                    ; $BBCB
    bne     @done                   ; $BBCD
; (code below not executed in the test movies)
    lda     rng+1,x                 ; $BBCF  3 in 4: come again
    and     #$03                    ; $BBD2
    bne     Boss_ResetState         ; $BBD4
; (end of code not executed in the test movies)

@done:
    rts                             ; $BBD6

@near:
    lda     enemyType,x             ; $BBD7  Horsehead:
    cmp     #$20                    ; $BBD9
    bne     @newCount               ; $BBDB
    lda     rng+1,x                 ; $BBDD  1 in 8, not swinging,
    and     #$07                    ; $BBE0
    ora     objState+1,x            ; $BBE2
    bne     @newCount               ; $BBE4
    lda     objFacing+1,x           ; $BBE6  and facing Link:
    pha                             ; $BBE8
    jsr     Enemy_FaceLink          ; $BBE9
    pla                             ; $BBEC
    sta     objFacing+1,x           ; $BBED
    iny                             ; $BBEF
    tya                             ; $BBF0
    cmp     objFacing+1,x           ; $BBF1
    bne     @newCount               ; $BBF3
    jsr     Enemy_StartSwing        ; $BBF5  swing

@newCount:
    lda     enemyAiState,x          ; $BBF8  count out,
    asl     a                       ; $BBFA
    bne     @done2                  ; $BBFB
    lda     rng+1,x                 ; $BBFD  1 in 8:
    and     #$07                    ; $BC00
    bne     @done2                  ; $BC02
    jsr     Boss_ResetState         ; $BC04  a new count ($10),
    lda     rng+1,x                 ; $BC07  toward or away
    and     #$80                    ; $BC0A
    ora     enemyAiState,x          ; $BC0C
    sta     enemyAiState,x          ; $BC0E

@done2:
    rts                             ; $BC10

; ---------------------------------------------------------------------------
; HorseHead_Attack
;
; Horsehead's swing: pose 1 (mace raised behind him) for 15 frames, pose 2
; (swung in front) for 15, then 15 frames of rest (pose $FF -> 0).
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
HorseHead_Attack:
    lda     objState+1,x            ; $BC11  swinging,
    beq     Enemy_StartSwing_Done   ; $BC13
    ldy     timerFast+TIMER_ENEMY,x ; $BC15  pose over?
    bne     Enemy_StartSwing_Done   ; $BC18
    lda     objState+1,x            ; $BC1A
    cmp     #$02                    ; $BC1C  pose 1: on to 2
    bne     Enemy_StartSwing        ; $BC1E
    dey                             ; $BC20  pose 2: rest ($FF -> 0)
    sty     objState+1,x            ; $BC21

; ---------------------------------------------------------------------------
; Enemy_StartSwing
;
; Start a sword or mace swing, or its next pose: objState+1 + 1, for 15
; frames (timerFast+TIMER_ENEMY).
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
Enemy_StartSwing:
    inc     objState+1,x            ; $BC23
    lda     #$0F                    ; $BC25
    sta     timerFast+TIMER_ENEMY,x ; $BC27

Enemy_StartSwing_Done:
    rts                             ; $BC2A
; (unreferenced: $BC2B-$BC4D, 35 bytes)
    .byte   $20, $91, $DC, $A5, $0F, $69, $25, $C9, $4A, $90, $07, $A9, $40, $8D, $DE, $05; $BC2B
    .byte   $B0, $0B, $EE, $DE, $05, $AD, $DE, $05, $29, $40, $D0, $01, $C8, $B9, $54, $BA; $BC3B
    .byte   $95, $71, $60                                                   ; $BC4B

; ---------------------------------------------------------------------------
; Boss_UpdateCommon
;
; The first palace group's bosses, each frame: drawn, moved by knockback or
; velocity, their guard tested (Enemy_CheckProjectileHitsSpecial; a clink
; returns from here), probes and hit tests (Enemy_UpdateWithBg), contact
; damage.  When the hits have killed it (enemyActive no longer 1), it is
; kept active as a dying boss: hitbox $FF (which Boss_UpdateIntro looks
; for), timer $FF, stun $7F (the flashing); and the rest of the caller's
; AI is skipped.
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
Boss_UpdateCommon:
    jsr     Enemy_Draw              ; $BC4E
    jsr     Enemy_KnockBackOrWalk_Bank4 ; $BC51
    jsr     Enemy_CheckProjectileHitsSpecial ; $BC54
    jsr     Enemy_UpdateWithBg      ; $BC57
    jsr     Enemy_HurtLinkOnContact ; $BC5A
    lda     #$01                    ; $BC5D  still alive?
    cmp     enemyActive,x           ; $BC5F
    beq     @done                   ; $BC61
    sta     enemyActive,x           ; $BC63  killed: keep it active,
    lda     #$FF                    ; $BC65  dying (hitbox $FF)
    ldy     enemyType,x             ; $BC67
    sta     sramEnemyHitbox,y       ; $BC69
    sta     timerFast+TIMER_ENEMY,x ; $BC6C
    lsr     a                       ; $BC6F  flashing 127 frames
    sta     enemyStunTimer,x        ; $BC70
    pla                             ; $BC73  and skip the caller's rest
    pla                             ; $BC74

@done:
    rts                             ; $BC75

; Helmethead_Init, by region (0: Helmethead, else Gooma): hit points (48,
; 144), and type $21's attributes, damage and hitbox in SRAM.
HelmetheadHp:
    .byte   $30, $90                                                        ; $BC76

HelmetheadAttrs:
    .byte   $CB, $CD                                                        ; $BC78

HelmetheadDamages:
    .byte   $32, $35                                                        ; $BC7A

HelmetheadHitboxes:
    .byte   $07, $11                                                        ; $BC7C

; ---------------------------------------------------------------------------
; Helmethead_Init
;
; Spawn routine of type $21 in the first palace group: Boss_Init, then by
; region Helmethead's or Gooma's hit points, and type $21's attributes,
; damage and hitbox (sramEnemyAttr+33, ...): the same type is Helmethead
; in palace 2 and Gooma in palace 5.
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
Helmethead_Init:
    jsr     Boss_Init               ; $BC7E
    ldy     #$00                    ; $BC81  0 Helmethead,
    lda     currentRegion           ; $BC83
    beq     @set                    ; $BC86
    iny                             ; $BC88  1 Gooma

@set:
    lda     HelmetheadHp,y          ; $BC89
    sta     enemyHp,x               ; $BC8C
    lda     HelmetheadAttrs,y       ; $BC8E
    sta     sramEnemyAttr+33        ; $BC91
    lda     HelmetheadDamages,y     ; $BC94
    sta     sramEnemyDamage+33      ; $BC97
    lda     HelmetheadHitboxes,y    ; $BC9A
    sta     sramEnemyHitbox+33      ; $BC9D
    rts                             ; $BCA0

; ---------------------------------------------------------------------------
; Boss_Init
;
; Spawn routine of the first palace group's bosses: only while the area's
; flag is set (not yet beaten; Area_TestFlag 1), else removed at once.
; Guard 2 (enemyAiVar) and hitbox entry 7 for its type.
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
Boss_Init:
    ldx     #$01                    ; $BCA1  beaten already?
    jsr     Area_TestFlag           ; $BCA3
    ldx     currentObject           ; $BCA6
    cmp     #$00                    ; $BCA8
    bne     @setUp                  ; $BCAA
; (code below not executed in the test movies)
    sta     enemyActive,x           ; $BCAC  yes: gone
    rts                             ; $BCAE
; (end of code not executed in the test movies)

@setUp:
    lda     #$02                    ; $BCAF  guard 2
    sta     enemyAiVar,x            ; $BCB1
    lda     #$07                    ; $BCB4  hitbox entry 7
    ldy     enemyType,x             ; $BCB6
    sta     sramEnemyHitbox,y       ; $BCB8
    rts                             ; $BCBB

; ---------------------------------------------------------------------------
; Tinsuit_Ai
;
; Tinsuit ($0C, first palace group): hops along the floor, 1 pixel per
; frame up on each landing (a hop about 4 pixels high, every 16 frames),
; turning around at walls; it doesn't turn toward Link.  enemyAiState
; counts the hops (the drawing alternates).
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
Tinsuit_Ai:
    jsr     Enemy_SkipAiIfStunned   ; $BCBC
    jsr     Enemy_UpdateWithBg      ; $BCBF
    jsr     Enemy_HurtLinkOnContact ; $BCC2
    lda     objCollision+1,x        ; $BCC5  on the floor: hop
    and     #$04                    ; $BCC7
    beq     @fall                   ; $BCC9
    jsr     Enemy_Land              ; $BCCB
    lda     #$F0                    ; $BCCE  Y velocity -1
    sta     objYVelocity+1,x        ; $BCD0
    inc     enemyAiState,x          ; $BCD3

@fall:
    jsr     Enemy_MoveYAndFall      ; $BCD5
    lda     objCollision+1,x        ; $BCD8  at a wall: turn
    and     #$03                    ; $BCDA
    beq     @move                   ; $BCDC
    jsr     Enemy_TurnAround        ; $BCDE

@move:
    jmp     Enemy_MoveX             ; $BCE1

; HelmetheadHead_Ai: the wave's top speeds and acceleration (by state
; bit 0), the drift toward Link (by Enemy_FaceLink's y) and the bounces.
HelmetheadHeadMaxYSpeeds:
    .byte   $18, $E8                                                        ; $BCE4

HelmetheadHeadYAccel:
    .byte   $01, $FF                                                        ; $BCE6

HelmetheadHeadXSpeeds:
    .byte   $06, $FA, $00, $FF                                              ; $BCE8

HelmetheadHeadYSpeeds:
    .byte   $E0, $F0, $F8                                                   ; $BCEC

; ---------------------------------------------------------------------------
; HelmetheadHead_Ai
;
; A helmet knocked off Helmethead ($22): drawn and harmful to touch, but
; never tested for hits.  It falls and bounces on the floor (Y $C4) 3 times
; (enemyAiState 0-2), each time up at HelmetheadHeadYSpeeds (-2, -1, -1/2)
; with a sound, its X velocity halved, and a 48-frame timer.  Then it lies
; there until the timer runs out, rises 2 pixels per frame to Y $70, and
; flies for good (enemyAiVar nonzero): up and down in a wave (Y velocity
; between +1.5 and -1.5 by 1/16 per frame), drifting toward Link at 6/16
; pixel per frame from each frameCounter 0, and firing an aimed ball
; (Enemy_FireAimedBall) every 128 frames (enemyAiDir counts).
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
HelmetheadHead_Ai:
    jsr     Enemy_Draw              ; $BCEF
    jsr     Enemy_CheckLinkContact  ; $BCF2
    jsr     Enemy_HurtLinkOnContact ; $BCF5
    jsr     Enemy_MoveX             ; $BCF8
    lda     objY+1,x                ; $BCFB
    ldy     enemyAiState,x          ; $BCFD  bounced 3 times?
    cpy     #$03                    ; $BCFF
    bcs     @rest                   ; $BD01
    cmp     #$C4                    ; $BD03  on the floor: bounce
    bcc     @fall                   ; $BD05
    lda     #$30                    ; $BD07  48 frames
    sta     timerFast+TIMER_ENEMY,x ; $BD09
    inc     enemyAiState,x          ; $BD0C
    lda     HelmetheadHeadYSpeeds,y ; $BD0E  up, less each time
    sta     objYVelocity+1,x        ; $BD11
    lda     #$10                    ; $BD14  a sound
    sta     sfxRequest+2            ; $BD16
    lda     #$C3                    ; $BD18
    sta     objY+1,x                ; $BD1A
    lda     objXVelocity+1,x        ; $BD1C  X speed halved
    asl     a                       ; $BD1E
    ror     objXVelocity+1,x        ; $BD1F

@fall:
    jmp     Enemy_MoveYAndFall      ; $BD21

@rest:
    ldy     enemyAiVar,x            ; $BD24  flying already,
    bne     @fly                    ; $BD27
    cmp     #$70                    ; $BD29  or up to Y $70?
    bcc     @fly                    ; $BD2B
    lda     #$00                    ; $BD2D  no: lie still,
    sta     objXVelocity+1,x        ; $BD2F
    sta     objYVelocity+1,x        ; $BD31
    ldy     timerFast+TIMER_ENEMY,x ; $BD34  then rise 2 px/frame
    bne     @done                   ; $BD37
    dec     objY+1,x                ; $BD39
    dec     objY+1,x                ; $BD3B

@done:
    rts                             ; $BD3D
; (code below not executed in the test movies)

@fly:
    sta     enemyAiVar,x            ; $BD3E  flying (nonzero)
    jsr     Enemy_MoveY             ; $BD41
    lda     enemyAiState,x          ; $BD44  the wave: accelerate down
    and     #$01                    ; $BD46  (odd) or up (even)
    tay                             ; $BD48
    lda     objYVelocity+1,x        ; $BD49
    clc                             ; $BD4C
    adc     HelmetheadHeadYAccel,y  ; $BD4D
    sta     objYVelocity+1,x        ; $BD50
    cmp     HelmetheadHeadMaxYSpeeds,y ; $BD53  at the top speed: turn
    bne     @drift                  ; $BD56
    inc     enemyAiState,x          ; $BD58

@drift:
    lda     frameCounter            ; $BD5A  every 256 frames:
    bne     @fire                   ; $BD5C
    jsr     Enemy_FaceLink          ; $BD5E  drift toward Link
    lda     HelmetheadHeadXSpeeds,y ; $BD61
    sta     objXVelocity+1,x        ; $BD64

@fire:
    inc     enemyAiDir,x            ; $BD66  every 128 frames:
    lda     enemyAiDir,x            ; $BD69
    asl     a                       ; $BD6C
    bne     HelmetheadHead_Ai_Done  ; $BD6D
    jsr     Enemy_FireAimedBall     ; $BD6F  an aimed ball
; (end of code not executed in the test movies)

HelmetheadHead_Ai_Done:
    rts                             ; $BD72
; The rts byte is also the base of the table HelmetheadHeadXOffsets (entry 0
; is the rts): by facing, -4, +4.
HelmetheadHeadXOffsets := HelmetheadHead_Ai_Done
    .byte   $FC                                                             ; $BD73
    .byte   $04                                                             ; $BD74

; ---------------------------------------------------------------------------
; Helmethead_Draw
;
; Draw Helmethead (or Gooma_Draw in palace 5): his body, two pairs from
; sramEnemyTiles entry $6C, or $70 in part of each 8-count step while he
; walks (as Horsehead); then his head, a pair from entry $74 + 2 x helmets
; lost (HelmetheadHead_DrawPart), 12 pixels above his top sprite, lowered
; by helmetheadHitDelay.  While alive and facing away from Link, the head
; is mirrored to look at him.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Helmethead_Draw:
    lda     currentRegion           ; $BD75  palace 5: Gooma
    beq     @helmethead             ; $BD78
    jmp     Gooma_Draw              ; $BD7A

@helmethead:
    ldy     #$50                    ; $BD7D
    lda     enemyAiState,x          ; $BD7F  standing: $6C
    ldx     #$6C                    ; $BD81
    and     #$7F                    ; $BD83
    beq     @body                   ; $BD85
    and     #$07                    ; $BD87  walking: $70 on counts
    sec                             ; $BD89  3-5 of each 8
    sbc     #$03                    ; $BD8A
    cmp     #$03                    ; $BD8C
    bcs     @body                   ; $BD8E
    ldx     #$70                    ; $BD90

@body:
    jsr     Sprite_DrawEnemyPair    ; $BD92
    jsr     Sprite_DrawEnemyPairKeepX ; $BD95
    lda     drawOffscreen+1         ; $BD98
    and     #$0C                    ; $BD9A
    bne     HelmetheadHead_Ai_Done  ; $BD9C
    lda     oamBuffer - 16,y        ; $BD9E  the head: 12 above his top
    sec                             ; $BDA1
    sbc     #$0C                    ; $BDA2
    adc     helmetheadHitDelay      ; $BDA4  (lowered after a hit)
    sta     temp0                   ; $BDA7
    ldy     #$60                    ; $BDA9
    jsr     HelmetheadHead_DrawPart ; $BDAB
    lda     sramEnemyHitbox+33      ; $BDAE  dying?
    bmi     @done                   ; $BDB1
    lda     objFacing+1,x           ; $BDB3  facing Link?
    pha                             ; $BDB5
    jsr     Enemy_FaceLink          ; $BDB6
    pla                             ; $BDB9
    sta     objFacing+1,x           ; $BDBA
    iny                             ; $BDBC
    tya                             ; $BDBD
    cmp     objFacing+1,x           ; $BDBE
    beq     @done                   ; $BDC0
; (code below not executed in the test movies)
    lda     oamBuffer+98            ; $BDC2  no: mirror the head
    eor     #$40                    ; $BDC5
    sta     oamBuffer+98            ; $BDC7
    sta     oamBuffer+102           ; $BDCA
; (end of code not executed in the test movies)

@done:
    rts                             ; $BDCD

; HelmetheadHead_Draw: OAM offset of each flying helmet, by its number.
HelmetheadHeadOamOffsets:
    .byte   $68, $80                                                        ; $BDCE

; ---------------------------------------------------------------------------
; HelmetheadHead_Draw
;
; Draw a flying helmet: a pair from entry $74 + 2 x its number (the
; helmet as it was on his head), at OAM offset $68 or $80.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
HelmetheadHead_Draw:
    ldy     objState+1,x            ; $BDD0
    lda     HelmetheadHeadOamOffsets,y ; $BDD2
    tay                             ; $BDD5

; ---------------------------------------------------------------------------
; HelmetheadHead_DrawPart
;
; Draw a pair from sramEnemyTiles entry $74 + 2 x objState+1 at temp0, with
; X shifted 4 pixels toward the facing (HelmetheadHeadXOffsets).
;
; In:      x = enemy index, y = OAM offset
; Status:  confirmed
; ---------------------------------------------------------------------------
HelmetheadHead_DrawPart:
    ldx     temp2                   ; $BDD6  X: -4 or +4 by facing
    lda     temp1                   ; $BDD8
    clc                             ; $BDDA
    adc     HelmetheadHeadXOffsets,x ; $BDDB
    sta     temp1                   ; $BDDE
    ldx     currentObject           ; $BDE0
    lda     objState+1,x            ; $BDE2  entry $74 + 2n
    asl     a                       ; $BDE4
    adc     #$74                    ; $BDE5
    tax                             ; $BDE7
; Stalfos_Draw: sword X offset by facing, the bytes after the jmp: +16, -16.
StalfosDrawOffsets := * + 2
    jmp     Sprite_DrawEnemyPairKeepX ; $BDE8
    .byte   $10, $F0                                                        ; $BDEB

; ---------------------------------------------------------------------------
; Stalfos_Draw
;
; Draw a Stalfos (it turns toward Link here as well): two pairs of sprites
; from sramEnemyTiles entry:
; - in the air: $34 rising; falling, $38 (front-on, both halves mirrored
;   to match) until it has first landed (enemyLanded), then $38, or $30
;   when 48 or more pixels from Link;
; - on the ground: $2C, alternating with $30 every 8 frames; $42/$46 in the
;   wind-up (pose 1, + $16); $3C slashing (pose 2), with the sword, a pair
;   from entry $40 beside it (StalfosDrawOffsets: 16 right or 16 left) at
;   its Y.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Stalfos_Draw:
    tya                             ; $BDED
    pha                             ; $BDEE
    jsr     Enemy_FaceLink          ; $BDEF  face Link (temp15 = dx)
    pla                             ; $BDF2
    tay                             ; $BDF3
    lda     enemyLanded,x           ; $BDF4
    sta     temp14                  ; $BDF7
    lda     #$00                    ; $BDF9  entry offset
    sta     temp13                  ; $BDFB
    lda     objYVelocity+1,x        ; $BDFD  in the air?
    beq     @onGround               ; $BE00
    ldx     #$34                    ; $BE02  rising: $34
    asl     a                       ; $BE04
    bcs     @draw                   ; $BE05
    lda     temp14                  ; $BE07  falling, not yet landed:
    beq     @frontOn                ; $BE09  front-on
    lda     temp15                  ; $BE0B  near Link (within 48)?
    adc     #$30                    ; $BE0D
    cmp     #$60                    ; $BE0F
    bcs     @walk2                  ; $BE11  no: $30

@frontOn:
    ldx     #$38                    ; $BE13  $38
    jmp     @draw                   ; $BE15

@onGround:
    lda     objState+1,x            ; $BE18  pose
    ldx     #$3C                    ; $BE1A  slashing: $3C
    cmp     #$02                    ; $BE1C
    bcs     @draw                   ; $BE1E
    lsr     a                       ; $BE20  winding up: + $16
    bcc     @walk                   ; $BE21
    lda     #$16                    ; $BE23
    sta     temp13                  ; $BE25

@walk:
    ldx     #$2C                    ; $BE27  $2C / $30 every 8 frames
    lda     frameCounter            ; $BE29
    and     #$08                    ; $BE2B
    beq     @draw                   ; $BE2D

@walk2:
    ldx     #$30                    ; $BE2F

@draw:
    stx     drawScratch             ; $BE31
    txa                             ; $BE33
    clc                             ; $BE34
    adc     temp13                  ; $BE35
    tax                             ; $BE37
    jsr     Sprite_DrawEnemyPair    ; $BE38  top pair
    jsr     Sprite_DrawEnemyPairKeepX ; $BE3B  bottom pair
    lda     drawScratch             ; $BE3E  front-on ($38):
    cmp     #$38                    ; $BE40
    bne     @sword                  ; $BE42
    lda     oamBuffer - 14,y        ; $BE44  left halves as drawn,
    and     #$3F                    ; $BE47
    sta     oamBuffer - 14,y        ; $BE49
    sta     oamBuffer - 6,y         ; $BE4C
    ora     #$40                    ; $BE4F  right halves mirrored
    sta     oamBuffer - 10,y        ; $BE51
    sta     oamBuffer - 2,y         ; $BE54

@sword:
    lda     objState+1,x            ; $BE57  slashing,
    cmp     #$02                    ; $BE59
    bne     @done                   ; $BE5B
    lda     drawOffscreen+1         ; $BE5D  on screen, on the ground?
    ora     objYVelocity+1,x        ; $BE5F
    bne     @done                   ; $BE62
    tya                             ; $BE64
    pha                             ; $BE65
    ldy     objFacing+1,x           ; $BE66  the sword beside it
    lda     temp1                   ; $BE68
    adc     StalfosDrawOffsets,y    ; $BE6A
    sta     temp1                   ; $BE6D
    lda     objY+1,x                ; $BE6F  at its Y
    sta     temp0                   ; $BE71
    pla                             ; $BE73
    tay                             ; $BE74
    ldx     #$40                    ; $BE75  entry $40
    jmp     Sprite_DrawEnemyPairKeepX ; $BE77

@done:
    rts                             ; $BE7A

; ---------------------------------------------------------------------------
; Mago_Draw
;
; Draw a Wizzrobe (first palace group): two pairs from sramEnemyTiles entry
; $1A, or $1E from count $D2 on (casting, then leaving).
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Mago_Draw:
    lda     enemyAiState,x          ; $BE7B
    ldx     #$1A                    ; $BE7D  $1A,
    cmp     #$D3                    ; $BE7F
    bcs     @draw                   ; $BE81
    ldx     #$1E                    ; $BE83  or $1E (casting)

@draw:
    jsr     Sprite_DrawEnemyPair    ; $BE85
    jmp     Sprite_DrawEnemyPairKeepX ; $BE88

; ---------------------------------------------------------------------------
; Boss_UpdateIntro
;
; The first palace group's boss fight, before the boss's own AI:
; - Until Link's screen reaches page 1 of the room (scrollXHi), the boss
;   is only drawn.  Then the boss music starts ($08) and the scroll
;   freezes (scrollFrozen).
; - Alive (its type's hitbox isn't $FF), its AI runs.
; - Dying (Boss_UpdateCommon), it is only drawn while its stun flashes.
;   When the stun runs out: enemyActive + 1 (the death bursts,
;   Boss_SpawnDeathSpark_Bank4), every enemy projectile is removed, every
;   other living enemy takes a hit (Enemy_TakeDamage with y = $0A, which
;   reads 224 points, the byte after ThunderDamage: enough to kill it), and
;   the music stops ($80).
;
; The code between the frame test and Enemy_TakeDamage never runs:
; drawScratch is always $0A there.
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
Boss_UpdateIntro:
    lda     scrollFrozen            ; $BE8B  fight on already?
    bne     @fightOn                ; $BE8E
    lda     scrollXHi               ; $BE90  Link not yet at page 1:
    beq     @drawOnly               ; $BE93  just draw it
    lda     #$08                    ; $BE95  boss music,
    sta     musicRequest            ; $BE97
    inc     scrollFrozen            ; $BE99  scroll frozen

@fightOn:
    ldy     enemyType,x             ; $BE9C  dying (hitbox $FF)?
    lda     sramEnemyHitbox,y       ; $BE9E
    bpl     @done                   ; $BEA1  no: on with its AI
    ldy     enemyStunTimer,x        ; $BEA3  still flashing: draw it
    bne     @drawOnly               ; $BEA6
    inc     enemyActive,x           ; $BEA8  burst
    lda     #$0A                    ; $BEAA
    sta     drawScratch             ; $BEAC
    lda     currentObject           ; $BEAE
    pha                             ; $BEB0
    ldx     #$05                    ; $BEB1  every slot:

@loop:
    stx     currentObject           ; $BEB3
    lda     #$00                    ; $BEB5  projectile gone
    sta     objState+7,x            ; $BEB7
    lda     enemyActive,x           ; $BEB9  a living enemy:
    beq     @next                   ; $BEBB
    cmp     #$01                    ; $BEBD
    bne     @next                   ; $BEBF
    inx                             ; $BEC1
    ldy     #$01                    ; $BEC2
    jsr     Obj_ComputeScreenPos    ; $BEC4
    ldx     currentObject           ; $BEC7
    ldy     drawScratch             ; $BEC9  (always $0A)
    bne     @hit                    ; $BECB
; (code below not executed in the test movies)
    lda     drawOffscreen+1         ; $BECD
    and     #$88                    ; $BECF
    bne     @next                   ; $BED1
    ldy     enemyType,x             ; $BED3
    lda     sramEnemyFlags,y        ; $BED5
    ldy     #$09                    ; $BED8
    and     #$A0                    ; $BEDA
    bmi     @next                   ; $BEDC
    beq     @hit                    ; $BEDE
    ldy     #$01                    ; $BEE0
; (end of code not executed in the test movies)

@hit:
    jsr     Enemy_TakeDamage        ; $BEE2  takes a hit

@next:
    dex                             ; $BEE5
    bpl     @loop                   ; $BEE6
    pla                             ; $BEE8
    sta     currentObject           ; $BEE9
    tax                             ; $BEEB
    lda     #$80                    ; $BEEC  music off
    sta     musicRequest            ; $BEEE

@drawOnly:
    pla                             ; $BEF0  skip the caller's AI
    pla                             ; $BEF1
    jmp     Enemy_Draw              ; $BEF2

@done:
    rts                             ; $BEF5

